// Booking creates the appointment — it does NOT enqueue the patient
async function checkIn(appointmentId: string) {
  await tokenQueue.create({
    appointmentId,
    status: 'WAITING',
    checkedInAt: new Date(),
  })
}

function assertBalanced(entries) {
  const total = entries.reduce(
    (sum, e) => sum + (e.type === 'DEBIT' ? e.amount : -e.amount),
    0,
  )
  if (total !== 0) throw new Error('Journal entry is not balanced')
}
